import { SiteFooter } from "march/landing"
import { Segmented } from "march/ui"

// mevsimlik alt bilgi: mevsim seçilince marka, kısa satır ve büyük yazı birlikte değişir
const SEASONS = {
  kış: { mark: "❄️", about: "Sıcak çikolata ve uzun sohbetler.", word: "KIŞ" },
  bahar: { mark: "🌸", about: "Parkta piknik, akşam yürüyüşü.", word: "BAHAR" },
  yaz: { mark: "☀️", about: "Sahil, dondurma, gece konserleri.", word: "YAZ" },
  güz: { mark: "🍂", about: "Yağmur, kitap ve filtre kahve.", word: "GÜZ" },
} as const

export function SeasonFooter() {
  let $season: keyof typeof SEASONS = "bahar"
  return <div sx={{ flex: "col", gap: 3 }}>
    <Segmented aria-label="Mevsim" options={Object.keys(SEASONS)} bind:value={$season} />
    {() => {
      const s = SEASONS[$season]
      return <SiteFooter brand={{ name: "Mevsim", mark: s.mark }} about={s.about} wordmark={s.word} toTop={false} />
    }}
  </div>
}

import { SiteFooter } from "march/landing"
import { toast } from "march/ui"
import { coffee, mapPin, mail, globe, message } from "march/icons"

// bir kahve dükkânının sitesinin alt bilgisi: sütunlar, sosyal bağlantılar, bülten ve yasal bağlantılar
const COLUMNS = [
  { title: "Dükkân", links: [{ label: "Menü", href: "#menu" }, { label: "Çekirdekler", href: "#cekirdek" }, { label: "Hediye kartı", href: "#hediye" }] },
  { title: "Ziyaret", links: [{ label: "Kadıköy şubesi", href: "#kadikoy" }, { label: "Beşiktaş şubesi", href: "#besiktas" }, { label: "Çalışma saatleri", href: "#saatler" }] },
  { title: "Biz", links: [{ label: "Hikâyemiz", href: "#hikaye" }, { label: "Kariyer", href: "#kariyer" }, { label: "İletişim", href: "#iletisim" }] },
]

export function CoffeeFooter() {
  return <SiteFooter brand={{ name: "Kahve Durağı", mark: coffee, sub: "2016'dan beri" }}
    about="Her sabah taze kavrulmuş çekirdek. Kadıköy ve Beşiktaş'ta, haftanın her günü."
    columns={COLUMNS}
    social={[{ label: "Harita", href: "#harita", icon: mapPin }, { label: "Web", href: "#", icon: globe }, { label: "Topluluk", href: "#", icon: message }, { label: "E-posta", href: "#", icon: mail }]}
    newsletter={{ title: "Haftanın çekirdeği", lead: "Her cuma bir yeni çekirdek, bir de indirim.", button: "Katıl", placeholder: "sen@ornek.com",
      onSubmit: () => { toast("Bültene katıldın") } }}
    copyright="© Kahve Durağı · Tüm hakları saklıdır"
    legal={[{ label: "Gizlilik", href: "#gizlilik" }, { label: "Çerezler", href: "#cerez" }, { label: "Mesafeli satış", href: "#satis" }]} />
}

import { SiteFooter } from "march/landing"
import { Toggle, Card } from "march/ui"
import { sparkles, globe, message, mail, chevronUp } from "march/icons"

// SiteFooter'ın bütün özellikleri bir arada: marka (özellikler ya da kendi düğümün), kısa satır, sütunlar, sosyal
// bağlantılar, bülten, telif satırı, yasal bağlantılar, büyük yazı, başa dön düğmesi, onun ikonu ve adı, sınıf
const COLUMNS = [
  { title: "Ürün", links: [{ label: "Özellikler", href: "#ozellikler" }, { label: "Fiyatlar", href: "#fiyatlar" }] },
  { title: "Şirket", links: [{ label: "Hakkımızda", href: "#hakkimizda" }, { label: "Kariyer", href: "#kariyer" }] },
]

// kendi düğümünden bir marka: harf bloğu ve ad
const OwnBrand = () => <strong sx={{ text: "lg", color: "brand-purple" }} class="lab-own-brand">◆ Atölye</strong>

export function SiteFooterLab() {
  let $own = false
  let $copy = true
  let $top = true
  let $mark = true
  let $subs = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Toggle label="Kendi markam" bind:value={$own} />
        <Toggle label="Telif satırı" bind:value={$copy} />
        <Toggle label="Başa dön" bind:value={$top} />
        <Toggle label="Büyük yazı" bind:value={$mark} />
      </div>
    </Card>
    {() => { const own = $own, copy = $copy, top = $top, mark = $mark; return <SiteFooter class="lab-footer"
      brand={own ? <OwnBrand /> as Node : { name: "Atölye", mark: sparkles, sub: "tasarım stüdyosu" }}
      about={() => `Küçük ekipler için tasarım araçları. ${$subs} abone`}
      columns={COLUMNS}
      social={[{ label: "Web", href: "#", icon: globe }, { label: "Topluluk", href: "#", icon: message }, { label: "E-posta", href: "#", icon: mail }]}
      newsletter={{ title: "Bülten", lead: "Ayda bir mektup.", button: "Abone ol", done: "Teşekkürler, görüşürüz!", motion: false,
        labels: { email: "E-posta adresin" }, onSubmit: () => { $subs++ } }}
      copyright={copy ? "© Atölye · İstanbul" : false}
      legal={[{ label: "Gizlilik", href: "#gizlilik" }, { label: "Koşullar", href: "#kosullar" }]}
      wordmark={mark ? "ATÖLYE" : undefined}
      toTop={top} toTopIcon={chevronUp} toTopLabel="Yukarı çık" /> }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { SiteFooterLab } from "./SiteFooterLab.tsx"

// SiteFooterLab'in testleri: kaydedince Testler sekmesinde çalışır
test("sütunlar başlıklarıyla adlandırılmış birer nav", () => {
  const s = renderTest(() => <SiteFooterLab />)
  const navs = s.all(".lab-footer nav.m-sfoot-col")
  expect(navs.length).toBe(2)
  expect(navs[0]!.getAttribute("aria-label")).toBe("Ürün")
  expect(s.container.querySelector('a[href="#kariyer"]')?.textContent).toBe("Kariyer")
})

test("telif satırı kendi metniyle; anahtar kapatınca gider", async () => {
  const s = renderTest(() => <SiteFooterLab />)
  expect(s.get(".m-sfoot-copy")?.textContent).toBe("© Atölye · İstanbul")
  await s.click("Telif satırı")
  expect(s.container.querySelector(".m-sfoot-copy")).toBe(null)
})

test("başa dön düğmesinin adı değişti; kendi markam düğümü gösterir", async () => {
  const s = renderTest(() => <SiteFooterLab />)
  expect(s.find("Yukarı çık")).not.toBe(null)
  await s.click("Başa dön")
  expect(s.container.querySelector(".m-sfoot-top-btn")).toBe(null)
  await s.click("Kendi markam")
  expect(s.container.querySelector(".lab-own-brand")).not.toBe(null)
})

test("bültene abone olunca teşekkür ve sayaç artar", async () => {
  const s = renderTest(() => <SiteFooterLab />)
  await s.type("E-posta adresin", "ayse@ornek.com")
  await s.click("Abone ol")
  await s.wait(() => s.sees("Teşekkürler, görüşürüz!"))
  expect(s.text()).toContain("1 abone")
})
